CREATE TABLE llx_cpo_board (rowid BIGINT AUTO_INCREMENT PRIMARY KEY, entity INT NOT NULL, title VARCHAR(255) NOT NULL, description TEXT, background VARCHAR(7) NOT NULL DEFAULT '#0c66e4', fk_usergroup INT NOT NULL, fk_user_creat INT NOT NULL, archived TINYINT NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, date_creation DATETIME NOT NULL, INDEX idx_cpo_board_entity(entity)) ENGINE=InnoDB;
CREATE TABLE llx_cpo_board_member (rowid BIGINT AUTO_INCREMENT PRIMARY KEY, entity INT NOT NULL, fk_board BIGINT NOT NULL, fk_user INT NOT NULL, role VARCHAR(12) NOT NULL, UNIQUE KEY uk_cpo_board_member(entity,fk_board,fk_user)) ENGINE=InnoDB;
CREATE TABLE llx_cpo_board_list (rowid BIGINT AUTO_INCREMENT PRIMARY KEY, entity INT NOT NULL, fk_board BIGINT NOT NULL, title VARCHAR(255) NOT NULL, position INT NOT NULL DEFAULT 0, archived TINYINT NOT NULL DEFAULT 0, INDEX idx_cpo_board_list(entity,fk_board)) ENGINE=InnoDB;
CREATE TABLE llx_cpo_board_card (rowid BIGINT AUTO_INCREMENT PRIMARY KEY, entity INT NOT NULL, fk_board BIGINT NOT NULL, fk_list BIGINT NOT NULL, fk_task BIGINT NOT NULL, position INT NOT NULL DEFAULT 0, archived TINYINT NOT NULL DEFAULT 0, UNIQUE KEY uk_cpo_board_task(entity,fk_task), INDEX idx_cpo_board_cards(entity,fk_board,fk_list)) ENGINE=InnoDB;
CREATE TABLE llx_cpo_card_grant (rowid BIGINT AUTO_INCREMENT PRIMARY KEY, entity INT NOT NULL, fk_task BIGINT NOT NULL, fk_user INT NOT NULL, role VARCHAR(12) NOT NULL, UNIQUE KEY uk_cpo_card_grant(entity,fk_task,fk_user)) ENGINE=InnoDB;
CREATE TABLE llx_cpo_board_pref (rowid BIGINT AUTO_INCREMENT PRIMARY KEY, entity INT NOT NULL, fk_board BIGINT NOT NULL, fk_user INT NOT NULL, starred TINYINT NOT NULL DEFAULT 0, last_opened DATETIME, UNIQUE KEY uk_cpo_board_pref(entity,fk_board,fk_user)) ENGINE=InnoDB;
CREATE TABLE llx_cpo_board_request (rowid BIGINT AUTO_INCREMENT PRIMARY KEY, entity INT NOT NULL, fk_user INT NOT NULL, request_hash CHAR(64) NOT NULL, digest CHAR(64) NOT NULL, fk_board BIGINT NOT NULL, UNIQUE KEY uk_cpo_board_request(entity,fk_user,request_hash)) ENGINE=InnoDB;
CREATE TABLE llx_cpo_board_background (entity INT NOT NULL, fk_board BIGINT NOT NULL, mime_type VARCHAR(32) NOT NULL, image_hash VARCHAR(64) NOT NULL, image_data MEDIUMTEXT NOT NULL, PRIMARY KEY(entity,fk_board)) ENGINE=InnoDB;
